import{_ as s,c as l,a,o as n}from"./app-C3KrGAW2.js";const i={};function r(p,e){return n(),l("div",null,[...e[0]||(e[0]=[a(`<h1 id="黑马点评项目笔记" tabindex="-1"><a class="header-anchor" href="#黑马点评项目笔记"><span>黑马点评项目笔记</span></a></h1><div style="background:#f8f9fa;padding:12px 16px;border-left:3px solid #4CAF50;margin-bottom:16px;border-radius:0 4px 4px 0;font-size:0.9rem;"><div style="display:flex;align-items:center;gap:30px;flex-wrap:wrap;"><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">📅</span><span>2024-01-26</span></div><div style="display:flex;align-items:center;gap:8px;"><span style="color:#666;">✍️</span><span>Jixer</span></div></div></div><h2 id="session共享问题" tabindex="-1"><a class="header-anchor" href="#session共享问题"><span>Session共享问题</span></a></h2><p>多台Tomcat并不共享session存储空间，当切换到不同的tomcat服务时导致数据丢失的问题</p><h2 id="缓存更新策略" tabindex="-1"><a class="header-anchor" href="#缓存更新策略"><span>缓存更新策略</span></a></h2><ul><li>内存淘汰：reids自带的内存淘汰机制</li><li>过期淘汰：利用exprie命令给数据设置过期时间</li><li>主动更新：主动完成数据库与reids的同时更新</li></ul><h3 id="策略选择" tabindex="-1"><a class="header-anchor" href="#策略选择"><span>策略选择</span></a></h3><ul><li>低一致性需求：内存淘汰或过期淘汰</li><li>高一致性需求：主动更新为主，过期淘汰为辅</li></ul><h3 id="关于主动更新策略的思考" tabindex="-1"><a class="header-anchor" href="#关于主动更新策略的思考"><span>关于主动更新策略的思考</span></a></h3><p>1、<strong>问题：是更新缓存还是删除缓存？</strong></p><p>更新缓存：会产生无效更新，因为有可能你更新了，系统一直没用上。并且存在较大的线程安全问题</p><p>删除缓存：本质是延迟更新，没有无效更新，线程安全问题相对较低</p><p>经过思考得出的最佳策略：<strong>删除缓存</strong></p><p>2、<strong>问题：先操作数据库还是缓存？</strong></p><p><strong>方案一：先删除缓存，再更新数据库</strong></p><p>正常情况：线程一先执行删除缓存，再更新数据库；线程二查询缓存有发现没有缓存，就查询数据库。</p><p>异常情况：线程一先执行删除缓存，这时候线程二到了，查询缓存后发现无缓存，就去查询数据库，这时候数据库的数据是没更新的数据，就出现了异常，最后线程一才执行更新数据库。</p><p><strong>方案二：先更新数据库，再删除缓存</strong></p><p>正常情况：线程一先更新数据库，再删除缓存，线程二查询缓存发现没有缓存，就查询数据库。</p><p>异常情况：线程二线查询缓存，发现有缓存，这时候线程一才到达，线程一就更新数据库，删除缓存，线程二就出现了异常，用的是没更新的数据。</p><p>经过思考得出的最佳策略：<strong>方案二</strong></p><p>3、<strong>如何确保数据库与缓存操作的原子性？</strong></p><p>单体系统：利用事务机制</p><p>分布式系统：利用分布式事务机制</p><h2 id="缓存穿透" tabindex="-1"><a class="header-anchor" href="#缓存穿透"><span>缓存穿透</span></a></h2><p>缓存穿透是指客户端请求的数据在缓存中和数据库中都不存在，这样缓存永远不会生效，这些请求都会打到数据库。</p><p><strong>解决方案</strong></p><ul><li>缓存空对象：请求到了后缓存一个值为null的数据到redis中 <ul><li>优点：简单，容易维护</li><li>缺点：1、额外的内存消耗。2、可能造成短期的不一致</li></ul></li><li>布隆过滤：在客户端和redis之间加个过滤器，用二进制数组判断是否存在。注意这个方法并不是百分百准确 <ul><li>优先：内存占用少</li><li>缺点：1、实现复杂。2、存在误判可能</li></ul></li></ul><h2 id="缓存雪崩" tabindex="-1"><a class="header-anchor" href="#缓存雪崩"><span>缓存雪崩</span></a></h2><p>缓存雪崩是指在同一时段大量的缓存key同时失效或者Redis服务宕机，导致大量请求到达数据库，带来巨大压力。</p><p><strong>解决方案</strong></p><ul><li>给不同的key设置不同的的过期时间</li><li>添加Redis集群提高服务可用性</li><li>给缓存添加降级限流策略</li><li>给业务添加多级缓存</li></ul><h2 id="缓存击穿" tabindex="-1"><a class="header-anchor" href="#缓存击穿"><span>缓存击穿</span></a></h2><p>缓存击穿问题也叫热点Key问题，就是一个被高并发访问并且缓存重建业务较复杂的key突然失效了，无数的请求访问会在瞬间给数据库带来巨大的冲击。</p><p><strong>解决方案</strong></p><ul><li>给热点接口添加互斥锁</li><li>逻辑过期【在redis中额外添加一个时间字段】</li></ul><h2 id="redis全局唯一id" tabindex="-1"><a class="header-anchor" href="#redis全局唯一id"><span>Redis全局唯一ID</span></a></h2><p><img src="https://s11.ax1x.com/2024/01/17/pFkCTn1.png" alt=""></p><ul><li>符号位：1bit，永远为0</li><li>时间戳：31bit，以秒为单位，可以用69年</li><li>序列号：32bit，秒内的计数器，支持每秒产生2^32个不同的ID</li></ul><h2 id="优惠券秒杀" tabindex="-1"><a class="header-anchor" href="#优惠券秒杀"><span>优惠券秒杀</span></a></h2><h3 id="超卖" tabindex="-1"><a class="header-anchor" href="#超卖"><span>超卖</span></a></h3><p><strong>解决办法</strong></p><ul><li>悲观锁：认为线程安全问题一定会发生，因此在操作数据之前先获取同步锁，确保线程串行执行。例如Synchronized、Lock都属于悲观锁 <ul><li>优点：简单粗暴</li><li>缺点：性能一般</li></ul></li><li>乐观锁：认为线程安全问题不一定会发生，因此不加锁，<strong>只是在更新数据时去判断有没有其它线程对数据做了修改</strong>。 <ul><li>如果没有修改则认为是安全的，自己才更新数据。</li><li>如果已经被其它线程修改说明发生了安全问题，此时可以重试或异常。</li><li>优点：性能好</li><li>缺点：存在成功率低的问题（需要做处理）</li></ul></li></ul><h4 id="悲观锁方法" tabindex="-1"><a class="header-anchor" href="#悲观锁方法"><span>悲观锁方法</span></a></h4><p>使用<code>synchronized</code>过于简单，采用乐观锁方法</p><h4 id="乐观锁方法" tabindex="-1"><a class="header-anchor" href="#乐观锁方法"><span>乐观锁方法</span></a></h4><blockquote><p>对于<strong>乐观锁</strong>的关键是判断之前查询得到的数据受否被修改过，常见的方法有两种：</p></blockquote><p>1、<strong>版本号法</strong></p><p><img src="https://s11.ax1x.com/2024/01/17/pFkM5m8.png" alt=""></p><p>2、<strong>CAS法</strong></p><p>CAS法和版本号法的区别在于CAS法是直接将库存和原来库做比较，而版本号法是比较的版本</p><p><img src="https://s11.ax1x.com/2024/01/17/pFkMOlq.png" alt=""></p><p><strong>弊端</strong>：出错率大大增加，100个库春，结果只有几十个成功卖出。为什么呢？</p><p>解答：假设有100个线程同时请求，只有一个线程成功，其他99线程都在最后一步扣减库存的时候需要判断是否和之前的库存一致出错了，所以就大大提高了错误率。</p><p><strong>怎么解决这个弊端？</strong></p><p>解答：将最后判断是否和之前库存一致改为<strong>只要库存大于0</strong>就行了</p><h3 id="一人一单" tabindex="-1"><a class="header-anchor" href="#一人一单"><span>一人一单</span></a></h3><p><strong>解决办法</strong>：使用乐观锁方法，添加同步代码<code>synchronized</code>，限制只有一个线程进入</p><p><strong>存在的问题</strong>：在单机模式下没问题，但在集群模式下就会出现问题，不同的SpringBoot服务中JVM使用的常量池、锁监视器是不一样，这导致了同一个用户两次请求都会进入到锁里，就出现了安全问题</p><p><img src="https://s11.ax1x.com/2024/01/18/pFkqadJ.png" alt=""></p><p><strong>解决办法</strong>：分布式锁，下面讲解分布式锁</p><h3 id="分布式锁" tabindex="-1"><a class="header-anchor" href="#分布式锁"><span>分布式锁</span></a></h3><p><strong>概念</strong>：满足分布式系统或集群模式下多进程可见并且互斥的锁</p><p><strong>满足的基本特性</strong>：多进程可见、高可用、互斥、好性能、安全性</p><p><strong>核心</strong>：实现多进程之间的互斥，下面是常见的三种</p><p><img src="https://s11.ax1x.com/2024/01/18/pFkL2cV.png" alt=""></p><p><strong>需要实现的两个基本方法</strong></p><ul><li>获取锁【通过<code>set lock name NX EX 10</code>来实现互斥锁并加上过期时间，NX是互斥，EX是设置超时时间】 <ul><li>互斥：确保只能有一个线程获取锁</li><li>非阻塞：尝试一次，成功返回true，失败返回false</li></ul></li><li>释放锁【<code>Del key</code>】 <ul><li>手动释放</li><li>超时释放</li></ul></li></ul><p><strong>分布式锁误删问题</strong>：因为线程一的某种原因导致阻塞，时间超过了Redis锁的过期时间，锁自动释放，线程二获取了线程一的锁，若此时线程一的业务执行完毕，就会手动调用释放锁，就把线程二的锁给释放了，出现了误删的情况</p><p><img src="https://s11.ax1x.com/2024/01/18/pFkjB7D.png" alt=""></p><p><strong>误删情况解决办法</strong>：获取锁的时候将value值设置为UUID+线程ID，每次释放锁的时候就拿redis中存放的值与这个值判断一下，相同才释放，否则不释放</p><p><strong>采用上诉方法还是存在问题</strong></p><p>释放锁的过程，是先判断reids中的值是否一致，再释放锁。可能出现在判断过后到是否锁之间出现阻塞的情况，因为在JVM中有个东西叫垃圾回收，它会阻塞代码。于是需要保证判断和释放这两部操作是原子操作，不可分割</p><p><img src="https://s11.ax1x.com/2024/01/18/pFAPylQ.png" alt=""></p><p><strong>解决办法</strong>：采用Lua脚本解决，编写Lua脚本，用Java调用</p><h4 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h4><p><strong>实现Reids分布式锁的思路</strong></p><ul><li>利用<code>set nx ex</code>获取锁，并设置过期时间，保存现场标识</li><li>释放锁先判断线程标识是否与自己一致，一致就删除锁【使用Lua脚本保证原子性】</li></ul><h2 id="redisson" tabindex="-1"><a class="header-anchor" href="#redisson"><span>Redisson</span></a></h2><p><strong>Redis的分布式锁是基于setnx实现的，存在一下问题</strong></p><ul><li>不可重入：同一个线程无法多次获取同一把锁</li><li>不可重试：获取锁只尝试一次就返回false，没有重试机制</li><li>超时释放：锁超时释放虽然可以避免死锁，但如果是业务执行耗时较长，也会导致锁释放，存在安全隐患</li><li>主从一致性：如果Redis提供了主从集群,主从同步存在延迟，当主宕机时，如果从并同步主中的锁数据，则会出现锁实现</li></ul><p><strong>Redisson提供一系列分布式的Java常用对象和许多分布式服务</strong></p><p><img src="https://s11.ax1x.com/2024/01/18/pFAEp5t.png" alt=""></p><h3 id="可重入锁原理" tabindex="-1"><a class="header-anchor" href="#可重入锁原理"><span>可重入锁原理</span></a></h3><p>通过redis的hash结构进行锁的存储，同一个线程进入，会将value值加一，并设置有效期，每次释放锁就value值减一。若减后的值不为0，就重置有效期，否则就直接删除。实现代码通过Lua脚本进行。</p><p><img src="https://s11.ax1x.com/2024/01/18/pFAVqne.png" alt=""></p><p><strong>流程图</strong></p><p><img src="https://s11.ax1x.com/2024/01/18/pFAZp1f.png" alt=""></p><h3 id="可重试锁原理" tabindex="-1"><a class="header-anchor" href="#可重试锁原理"><span>可重试锁原理</span></a></h3><p>利用信号量和PubSub功能实现等待、唤醒、获取锁失效的重试机制</p><p><img src="https://s11.ax1x.com/2024/01/18/pFAeYZQ.png" alt=""></p><h3 id="超时续约原理" tabindex="-1"><a class="header-anchor" href="#超时续约原理"><span>超时续约原理</span></a></h3><p>利用wathDog，每隔一段时间，重置超时时间</p><h3 id="主从一致性原理" tabindex="-1"><a class="header-anchor" href="#主从一致性原理"><span>主从一致性原理</span></a></h3><p>多个独立的Redis结点，必须所有的结点都获取重入锁，才算获取锁成功</p><h2 id="秒杀优化" tabindex="-1"><a class="header-anchor" href="#秒杀优化"><span>秒杀优化</span></a></h2><h3 id="思路" tabindex="-1"><a class="header-anchor" href="#思路"><span>思路</span></a></h3><ul><li>利用Reids Lua脚本完成库存余量、一人一单判断，完成抢单业务</li><li>再将下单业务放入阻塞队列中，利用独立线程异步下单</li></ul><h3 id="使用阻塞队列存在的问题" tabindex="-1"><a class="header-anchor" href="#使用阻塞队列存在的问题"><span>使用阻塞队列存在的问题</span></a></h3><ul><li>内存限制问题：当队列的元素超过容量的时候会出现内存溢出</li><li>数据安全问题：当队列的任务服务出现宕机，任务就会丢失</li></ul><h2 id="reids消息队列" tabindex="-1"><a class="header-anchor" href="#reids消息队列"><span>Reids消息队列</span></a></h2><h3 id="基于list结构模拟消息队列" tabindex="-1"><a class="header-anchor" href="#基于list结构模拟消息队列"><span>基于List结构模拟消息队列</span></a></h3><p>Reids中的List数据结构是一个双向链表，利用LPUSH结合RPOP，或者RPUSH结合LPOP来实现</p><p>不过需要注意的是，当消息队列没有消息时RPOP和LPOP操作会返回NULL，并不像JVM阻塞队列那样会阻塞并等待消息。</p><p>因此应该使用BRPOP或者BLPOP来实现阻塞效果</p><h4 id="优点" tabindex="-1"><a class="header-anchor" href="#优点"><span>优点</span></a></h4><ul><li>利用Reids存储，不受限于JVM内存上限</li><li>基于Reidis的持久化机制，数据安全性有保证</li><li>可以满足消息有序性</li></ul><h4 id="缺点" tabindex="-1"><a class="header-anchor" href="#缺点"><span>缺点</span></a></h4><ul><li>无法避免消息丢失</li><li>只支持单消费者</li></ul><h3 id="基于pubsub的消息队列" tabindex="-1"><a class="header-anchor" href="#基于pubsub的消息队列"><span>基于PubSub的消息队列</span></a></h3><p>生产者向对应的cahnnel发送消息后，所有订阅者都能收到消息【一对多】</p><ul><li>SUBSCRIBE channel [channel]：订阅一个或多个频道</li><li>PUSLISH channel msg：向一个频道发送消息</li><li>PSUBSCRIBE pattern [pattern]：订阅与pattern格式匹配的所有频道</li></ul><h4 id="优点-1" tabindex="-1"><a class="header-anchor" href="#优点-1"><span>优点</span></a></h4><ul><li>采用发布订阅模型，支持多生产、多消费</li></ul><h4 id="缺点-1" tabindex="-1"><a class="header-anchor" href="#缺点-1"><span>缺点</span></a></h4><ul><li>不支持数据持久化</li><li>无法避免消息丢失</li><li>消息堆积有上限，超出时数据丢失</li></ul><h3 id="基于stream类型消息队列" tabindex="-1"><a class="header-anchor" href="#基于stream类型消息队列"><span>基于Stream类型消息队列</span></a></h3><p>stream是一种数据类型，专门为消息队列设计的，相较于前面两种方式能够更加完美实现一个消息队列</p><p><strong>生产消息</strong>：用于向指定的Stream流中添加一个消息</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">XADD key *|ID value [value ...]</span>
<span class="line"></span>
<span class="line"># 创建名为 users 的队列，并向其中发送一个消息，内容是：{name=jack,age=21}，并且使用Redis自动生成ID</span>
<span class="line">127.0.0.1:6379&gt; XADD users * name jack age 21</span>
<span class="line">&quot;1644805700523-0</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>key就是消息队列，key不存(*)在会自动创建（默认），ID是消息表示，value是消息的内容</p><p><strong>消费消息</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">XREAD [COUNT count] [BLOCK milliseconds] STREAMS key [key ...] ID ID</span>
<span class="line"></span>
<span class="line"># 读取XREAD中的第一条消息</span>
<span class="line">XREAD COUNT 1 STREAMS users 0</span>
<span class="line"># 阻塞1秒钟后从XREAD中读取的最新消息</span>
<span class="line">XREAD COUNT 1 BLOCK 1000 STREAMS users $</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意：当我们指定起始ID为<code>$</code>时代表读取最后一条消息（读取最新的消息）ID为<code>0</code>时代表读最开始的一条消息（读取最旧的消息），如果我们处理一条消息的过程中，又有超过1条以上的消息到达队列，则下次获取时也只能获取到最新的一条，会出现漏读消息的问题</p><h4 id="特点" tabindex="-1"><a class="header-anchor" href="#特点"><span>特点</span></a></h4><ul><li>消息可回溯</li><li>一个消息可以被多个消费者读取</li><li>可以阻塞堆区</li><li>有消息漏读风险</li></ul><h4 id="消费者组" tabindex="-1"><a class="header-anchor" href="#消费者组"><span>消费者组</span></a></h4><p>上面我们介绍的消费方式都是<strong>单消费方式</strong>，容易发生消息堆积导致消息丢失，所以我们需要改用消费者组的模式</p><p><strong>消费者组</strong>：将多个消费者划分到一个组，监听同一队列</p><ul><li><strong>消息分流</strong>：队列中的消息会分流给组内的不同消费者，而不是重复消费，从而加快消息处理的速度</li><li><strong>消息标识</strong>：消费者组会维护一个标示，记录最后一个被处理的消息，哪怕消费者宕机重启，还会从标示之后读取消息。确保每一个消息都会被消费</li><li><strong>消息确认</strong>：消费者获取消息后，消息处于<code>pending</code>（待处理）状态，并存入一个<code>pending-list</code>。当处理完成后需要通过<code>XACK</code>来确认消息，标记消息为已处理，才会从pending-list移除。</li></ul><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line"># 创建消费者组</span>
<span class="line">XGROUP CREATE key groupName ID</span>
<span class="line"># 删除指定的消费者组</span>
<span class="line">XGROUP DESTORY key groupName</span>
<span class="line"># 给指定的消费者组添加消费者</span>
<span class="line">XGROUP CREATECONSUMER key groupName consumerName</span>
<span class="line"># 删除消费者组中指定消费者</span>
<span class="line">XGROUP DELCONSUMER key groupName consumerName</span>
<span class="line"># 从消费者组中读取消息</span>
<span class="line">XREADGROUP GROUP</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><img src="https://img-blog.csdnimg.cn/img_convert/27039c5d7c9c137c15bab614293a63fe.png" alt=""></p><p><img src="https://img-blog.csdnimg.cn/img_convert/c1ffb0ac9d815f997953b1dfeae6768f.png" alt=""></p><p><code>stream</code>类型消息队列的<code>XREADGROUP</code>命令特点：</p><ul><li>消息可回溯</li><li>可以多消费者争抢消息，加快消费速度</li><li>可以阻塞读取</li><li>没有消息漏读的风险</li><li>有消息确认机制，保证消息至少被消费一次</li></ul><h3 id="比较" tabindex="-1"><a class="header-anchor" href="#比较"><span>比较</span></a></h3><p><img src="https://s21.ax1x.com/2024/03/11/pF6P3RK.png" alt=""></p><h2 id="feed流" tabindex="-1"><a class="header-anchor" href="#feed流"><span>Feed流</span></a></h2><p>关注推送也叫投喂，为用户持续提供沉浸式体验，通过无限下拉刷新获取新的信息</p><h3 id="与传统模式的区别" tabindex="-1"><a class="header-anchor" href="#与传统模式的区别"><span>与传统模式的区别</span></a></h3><ul><li><p>传统模式：用户寻找内容</p></li><li><p>Feed模式：内容匹配用户</p></li></ul><h3 id="feed流常见的模式" tabindex="-1"><a class="header-anchor" href="#feed流常见的模式"><span>Feed流常见的模式</span></a></h3><ul><li>TimeLine：不做内容筛选，简单的按照内容发布时间排序，常用于好友或者关注</li><li>智能排序：利用智能算法屏蔽掉违规的、用户不感兴趣的内容</li></ul><h3 id="feed流实现方案" tabindex="-1"><a class="header-anchor" href="#feed流实现方案"><span>Feed流实现方案</span></a></h3><p><img src="https://s11.ax1x.com/2024/01/19/pFAoHxO.png" alt=""></p><h2 id="hyperloglog用法" tabindex="-1"><a class="header-anchor" href="#hyperloglog用法"><span>HyperLogLog用法</span></a></h2><p>首先搞懂两个概念</p><ul><li>UV：独立访客量，1天内一个用户多次访问该网站，只记录一次</li><li>PV：页面访问量：用户多次打开页面，记录多次PV</li></ul><p>UV统计</p><ul><li>优点：内存占用极小</li><li>缺点：存在0.81%的误差【不过可以完全忽略】</li></ul><h2 id="总结-1" tabindex="-1"><a class="header-anchor" href="#总结-1"><span>总结</span></a></h2><h3 id="_2024-1-16" tabindex="-1"><a class="header-anchor" href="#_2024-1-16"><span>2024-1-16</span></a></h3><p>1、写了发短信验证码和登录接口，随机生成token，将用户信息存入redis中</p><p>2、写了两个拦截器，一个拦截所有请求的token刷新拦截器【没有token直接放行，token中找不到数据直接放行，全部通过就存入UserHolder中】，一个是只拦截需要验证的登录拦截器【只需要检验UserHolder中是否有数据，有就通过，否则拦截】。</p><p>3、对查询商品接口做了缓存，并且对**缓存击穿【互斥锁】<strong>和</strong>缓存穿透【缓存空对象】**做了处理，用jmeter进行检验</p><h3 id="_2024-1-17" tabindex="-1"><a class="header-anchor" href="#_2024-1-17"><span>2024-1-17</span></a></h3><p>1、 用逻辑过期时间解决缓存击穿【在shop中使用expire字段】，<strong>使用这个方法需要将热点key提前预热</strong>。通过比较当前时间和逻辑时间，而从决定是否需要重建数据。通过互斥锁来保证只有一个线程能够进入，通过独立线程来重构数据来减少响应时间</p><p>2、创建了redis全局唯一ID生成器，通过符号位(1位)+时间错(31位)+序列号(32位)来形成一个唯一ID，但这样这个ID最大值并不满足总量的所需的范围要求，因此需要通过<strong>不同的key来生成序列号</strong>【通过加上<code>年:月:日</code>前缀】来保证每天的都有会不同的ID，这个最大值并不会超过一天所需的范围要求。</p><p>3、写了优惠券秒杀功能，正常写法会出现超卖的情况，使用<strong>乐观锁</strong>优化后加上库存限制解决超卖问题【这里也可以用悲观锁解决，通过互斥锁或者同步代码】；使用<strong>悲观锁</strong><code>synchronized</code>解决一人一单的问题，并用**代理事务【AopContext.currentProxy()】**解决事务</p><h3 id="_2024-1-18" tabindex="-1"><a class="header-anchor" href="#_2024-1-18"><span>2024-1-18</span></a></h3><p>1、一人一单集群模式下使用分布式锁解决，分布式锁带来了一系列问题，比如：两个服务的<code>synchronized (userId.toString().intern())</code>获取的对象不一致【<strong>通过互斥锁解决</strong>】，误删【<strong>通过每次释放前判断存入锁的值是否一致解决</strong>】，原子性问题【<strong>释放锁的操作分为判断是否一致和释放锁，需要用Java调用写好的Lua脚本来确保原子性</strong>】</p><p>2、整合Redisson，了解其可重入的原理，可重试锁原理、超时续约原理、主从一致性原理</p><p>3、新增查询笔记、点赞笔记</p><h3 id="_2024-1-19" tabindex="-1"><a class="header-anchor" href="#_2024-1-19"><span>2024-1-19</span></a></h3><p>1、点赞排行榜【采用redis的zSet存储，按照时间戳排序】、关注、共同关注【set集合取两个集合的并集】</p><p>2、使用Feed流，在博文发布的时候推送给关注自己的人</p><p>3、签到：使用二进制位<code>stringRedisTemplate.opsForValue().setBit(key, dayOfMonth - 1, true);</code>存储签到，签到了就是1，没签到就是0</p><p>4、统计连续签到，通过<code>stringRedisTemplate.opsForValue().bitField</code>来获取 本月截至今天为止所有的签到记录</p><h3 id="_2024-3-10" tabindex="-1"><a class="header-anchor" href="#_2024-3-10"><span>2024-3-10</span></a></h3><p>1、优化优惠券秒杀逻辑，将原本对数据库的查询等判断条件全部放到Lua脚本中，改为从Reids中判断，极大的优化了查询的时间</p><p>2、使用阻塞队列 + 线程池实现异步秒杀</p><h3 id="_2024-3-11" tabindex="-1"><a class="header-anchor" href="#_2024-3-11"><span>2024-3-11</span></a></h3><p>1、优化秒杀，使用Stream消息队列替换阻塞队列，能够弥补阻塞队列带来的问题，例如：内存上限，数据丢失等</p>`,173)])])}const d=s(i,[["render",r]]),h=JSON.parse('{"path":"/%E5%AE%9E%E6%88%98%E9%A1%B9%E7%9B%AE/%E9%BB%91%E9%A9%AC%E7%82%B9%E8%AF%84%E9%A1%B9%E7%9B%AE%E7%AC%94%E8%AE%B0.html","title":"黑马点评项目笔记","lang":"en-US","frontmatter":{},"headers":[{"level":2,"title":"Session共享问题","slug":"session共享问题","link":"#session共享问题","children":[]},{"level":2,"title":"缓存更新策略","slug":"缓存更新策略","link":"#缓存更新策略","children":[{"level":3,"title":"策略选择","slug":"策略选择","link":"#策略选择","children":[]},{"level":3,"title":"关于主动更新策略的思考","slug":"关于主动更新策略的思考","link":"#关于主动更新策略的思考","children":[]}]},{"level":2,"title":"缓存穿透","slug":"缓存穿透","link":"#缓存穿透","children":[]},{"level":2,"title":"缓存雪崩","slug":"缓存雪崩","link":"#缓存雪崩","children":[]},{"level":2,"title":"缓存击穿","slug":"缓存击穿","link":"#缓存击穿","children":[]},{"level":2,"title":"Redis全局唯一ID","slug":"redis全局唯一id","link":"#redis全局唯一id","children":[]},{"level":2,"title":"优惠券秒杀","slug":"优惠券秒杀","link":"#优惠券秒杀","children":[{"level":3,"title":"超卖","slug":"超卖","link":"#超卖","children":[]},{"level":3,"title":"一人一单","slug":"一人一单","link":"#一人一单","children":[]},{"level":3,"title":"分布式锁","slug":"分布式锁","link":"#分布式锁","children":[]}]},{"level":2,"title":"Redisson","slug":"redisson","link":"#redisson","children":[{"level":3,"title":"可重入锁原理","slug":"可重入锁原理","link":"#可重入锁原理","children":[]},{"level":3,"title":"可重试锁原理","slug":"可重试锁原理","link":"#可重试锁原理","children":[]},{"level":3,"title":"超时续约原理","slug":"超时续约原理","link":"#超时续约原理","children":[]},{"level":3,"title":"主从一致性原理","slug":"主从一致性原理","link":"#主从一致性原理","children":[]}]},{"level":2,"title":"秒杀优化","slug":"秒杀优化","link":"#秒杀优化","children":[{"level":3,"title":"思路","slug":"思路","link":"#思路","children":[]},{"level":3,"title":"使用阻塞队列存在的问题","slug":"使用阻塞队列存在的问题","link":"#使用阻塞队列存在的问题","children":[]}]},{"level":2,"title":"Reids消息队列","slug":"reids消息队列","link":"#reids消息队列","children":[{"level":3,"title":"基于List结构模拟消息队列","slug":"基于list结构模拟消息队列","link":"#基于list结构模拟消息队列","children":[]},{"level":3,"title":"基于PubSub的消息队列","slug":"基于pubsub的消息队列","link":"#基于pubsub的消息队列","children":[]},{"level":3,"title":"基于Stream类型消息队列","slug":"基于stream类型消息队列","link":"#基于stream类型消息队列","children":[]},{"level":3,"title":"比较","slug":"比较","link":"#比较","children":[]}]},{"level":2,"title":"Feed流","slug":"feed流","link":"#feed流","children":[{"level":3,"title":"与传统模式的区别","slug":"与传统模式的区别","link":"#与传统模式的区别","children":[]},{"level":3,"title":"Feed流常见的模式","slug":"feed流常见的模式","link":"#feed流常见的模式","children":[]},{"level":3,"title":"Feed流实现方案","slug":"feed流实现方案","link":"#feed流实现方案","children":[]}]},{"level":2,"title":"HyperLogLog用法","slug":"hyperloglog用法","link":"#hyperloglog用法","children":[]},{"level":2,"title":"总结","slug":"总结-1","link":"#总结-1","children":[{"level":3,"title":"2024-1-16","slug":"_2024-1-16","link":"#_2024-1-16","children":[]},{"level":3,"title":"2024-1-17","slug":"_2024-1-17","link":"#_2024-1-17","children":[]},{"level":3,"title":"2024-1-18","slug":"_2024-1-18","link":"#_2024-1-18","children":[]},{"level":3,"title":"2024-1-19","slug":"_2024-1-19","link":"#_2024-1-19","children":[]},{"level":3,"title":"2024-3-10","slug":"_2024-3-10","link":"#_2024-3-10","children":[]},{"level":3,"title":"2024-3-11","slug":"_2024-3-11","link":"#_2024-3-11","children":[]}]}],"git":{"updatedTime":1772378218000,"contributors":[{"name":"lijunxi","username":"lijunxi","email":"2770063826@qq.com","commits":2,"url":"https://github.com/lijunxi"}],"changelog":[{"hash":"9f2e2eae9bf1528af2a053782edcdc5a1967682a","time":1772378218000,"email":"2770063826@qq.com","author":"lijunxi","message":"add vuepress"},{"hash":"c0e7c2d63343d3254f23fa31134bceb4e00c3331","time":1751790745000,"email":"2770063826@qq.com","author":"lijunxi","message":"add algorithm、school"}]},"filePathRelative":"实战项目/黑马点评项目笔记.md"}');export{d as comp,h as data};
